Section StdioTT.
Context {St : Type}.

Lemma mloop_S_eq : forall {X R} n (body : X -> @M St (X + R)) x (st : St),
  mloop (S n) body x st = ebind (body x st) (fun p => (match fst p with inl x' => mloop n body x' | inr r => mret r end) (snd p)).
Proof.
