Theorem tok_wv_loop : forall chans n fd iovs (st : St),
  In fd chans -> (1 <= length iovs <= 2)%nat -> iov_total iovs < Z.of_nat n -> iov_total iovs <= 2^26 ->
  tok chans (mloop n (wv_body fd) iovs st).
